def uretim(code, ozet, birim, tesl_kabul, sure, kim='freelancer', ek=None, oran=55, extra_kapsam=None):
    small(code, ozet,
     [f'{birim} başına brif, üretim ve 1 revizyon', 'Marka şablonu ve sesiyle uyum', 'Platform boyutlarında teslim'] + (extra_kapsam or []),
     ['Yayın ve hesap yönetimi (SOS-04)', 'Reklam bütçesi'],
     [T(birim.capitalize(), tesl_kabul)],
     [G('Konu, ürün ve mesaj'), G('Görsel/video materyali', zorunlu=False)],
     [S('Brif ve metin taslağı', 'ai', 'ai_taslak', 1, None, None, 'Brif + metin', 'Marka sesine uygun'),
      S('Üretim', kim, 'insan', sure, None, None, birim.capitalize(), 'Şablon ve boyut doğru'),
      S('Kalite kontrolü', 'ai', 'tam', 1, None, 'Kabul ön kontrolü', 'Kontrol notu', 'Yazım, kontrast, boyut'),
      S('Müşteri onayı', 'musteri', 'insan', 2, 'onay', ONAY, 'Onaylı içerik', 'Karar kaydı var'),
      S('Revizyon ve teslim', kim, 'insan', 1, None, None, 'Son dosya', 'Revizyon notları uygulandı')], sure + 5,
     ['Revizyon oranı', 'Teslim süresi', 'İçerik başına etkileşim'], [R('Brif belirsiz', 'Claude brifi soru listesine çevirir, eksik bilgi istenir')],
     ['Claude brif ve metin taslağını marka sesi kılavuzuyla yazar; kalite kontrolünde yazım ve marka uyumunu denetler.'], ['Teslim dosyaları müşteri klasörüne ve proje notuna bağlanır.'], ek, oran)

